-- Follow the final log target and inspect numeric UID and regular-file type. Keep the legacy item disabled.
UPDATE t_baseline_item SET name='/var/log/messages 的最终目标为 UID 0 属主的普通文件', remediation='旧模板已停用。仅用于确实使用 /var/log/messages 的 GNU stat 主机；-L 查询符号链接的最终目标，%f 核对普通文件类型，%u 核对数值属主 UID 0。文件缺失、断链或查询失败是执行异常；目录等非普通文件不通过。不证明日志服务运行或全部日志权限。 由管理员按业务和发行版人工处置；本包不提供自动修复。', "check"='{"type":"cmd_output","cmd":"stat -L -c ''%f %u'' /var/log/messages","operator":"regex","expected":"^8[0-9a-f]{3} 0$","timeout_ms":5000}' WHERE template_id IN (SELECT id FROM t_baseline_template WHERE code='DJBH2.0-LINUX' AND package_id IS NULL) AND code='BL-LINUX-0030';
